import math
S={'mode':'rev','fwd_until':0.0,'pts':[], 'n':0}
def wrap(a):
    return (a+180.0)%360.0-180.0
def cl(x,a):
    return max(-a,min(a,x))
def control(obs):
    t=obs['t']; rig=obs['rig']; tr=rig['trailer_rear']; hitch=obs['hitch_deg']
    S['n']+=1
    views=obs.get('views') or {}
    pts=[]
    for name,v in views.items():
        if not v: continue
        ox,oy=v['origin']
        for w in v.get('walls',[]) or []:
            b,d=w[0],w[1]
            pts.append((ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b))))
    if pts: S['pts']=pts
    else: pts=S['pts']
    look=-23
    if S['mode']=='fwd':
        if t<S['fwd_until'] and abs(hitch)>8:
            return (cl(-2.0*hitch,34),0.8,look)
        S['mode']='rev'
    if abs(hitch)>42:
        S['mode']='fwd'; S['fwd_until']=t+3.0
        return (cl(-2.0*hitch,34),0.8,look)
    back=180.0+rig['trailer_heading_deg']
    tx,ty=tr
    goal=None
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        ex,ey=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        gx=ex+d*math.cos(b); gy=ey+d*math.sin(b)
        goal=math.degrees(math.atan2(gy-ty,gx-tx))
    if goal is None:
        best=None;bs=-1e9
        for k in range(-20,21):
            th=back+3*k
            c=math.cos(math.radians(th)); s=math.sin(math.radians(th))
            reach=12.0
            for (px,py) in pts:
                dx=px-tx; dy=py-ty
                a=dx*c+dy*s; lat=-dx*s+dy*c
                if a>0.2 and abs(lat)<1.15 and a<reach: reach=a
            sc=reach-0.03*abs(3*k)
            if sc>bs: bs=sc;best=th
        goal=best if best is not None else back
    L=-wrap(goal-back)
    c=math.cos(math.radians(back)); s=math.sin(math.radians(back))
    lm=None;rm=None
    for (px,py) in pts:
        dx=px-tx; dy=py-ty
        a=dx*c+dy*s; lat=-dx*s+dy*c
        if -2.5<a<1.5:
            if lat<0:
                # lat negative = left? compute: left of backward axis
                pass
    # left of backward direction: rotate; backward axis pointing back, left side (vehicle-left) has lat<0 when facing back
    for (px,py) in pts:
        dx=px-tx; dy=py-ty
        a=dx*c+dy*s; lat=-dx*s+dy*c
        if -2.5<a<1.5:
            if lat<0:
                v=-lat
                if lm is None or v<lm: lm=v
            else:
                if rm is None or lat<rm: rm=lat
    if lm is not None and rm is not None and lm<3 and rm<3:
        L+=cl(8.0*(lm-rm)/2.0,12)
    hdes=cl(1.0*L,30)
    steer=cl(2.0*(hitch-hdes),34)
    if S['n']%30==0:
        print('t=%.1f h=%.1f back=%.0f goal=%.0f L=%.1f hdes=%.1f st=%.1f lm=%s rm=%s tg=%s'%(t,hitch,back,goal,L,hdes,steer,lm,rm,tg.get('in_sight')))
    return (steer,-1.0,look)

