tries=[(-35,0.6),(0,0.6),(-45,-0.5),(35,0.6),(45,-0.5)]
ti=0;stuck=0.0;moved=0.0;done=False;lastp=-10
def control(obs):
    global ti,stuck,moved,done,lastp
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];hold=obs['motion'].get('hold_s',0) or 0
    phi=obs['hitch_deg']
    if done: return (obs['steer_deg'],0.0,-150)
    st,sp=tries[ti]
    moved+=abs(v)*dt
    if moved>1.6:
        done=True;wake('freed: moved %.1f with steer %d spd %.1f phi %.1f'%(moved,st,sp,phi))
        return (st,0.0,-150)
    if hold<=0 and abs(v)<0.03 and abs(obs['steer_deg']-st)<2:
        stuck+=dt
        if stuck>2.5:
            stuck=0.0;ti+=1
            if ti>=len(tries):
                done=True;wake('all tries stuck phi %.1f'%phi);return (0,0.0,-150)
    else: stuck=0.0
    t=obs.get('t',0)
    if t-lastp>=1.5:
        lastp=t;print('t%.1f try%d st%d sp%.1f v%.2f moved%.2f phi%.1f %s'%(t,ti,st,sp,v,moved,phi,obs.get('status')))
    return (st,sp,-150)

