import math
L1=1.25
alley=0.0
width=3.7
phase='rev'
last_cy=None

def clamp(x,a,b):
    return max(a,min(b,x))

def fit(pts):
    n=len(pts)
    if n<2: return None
    mx=sum(p[0] for p in pts)/n; my=sum(p[1] for p in pts)/n
    sxx=sum((p[0]-mx)**2 for p in pts)
    if sxx<0.3: return (my,None,mx)
    sxy=sum((p[0]-mx)*(p[1]-my) for p in pts)
    return (my,sxy/sxx,mx)

def control(obs):
    global alley,width,phase,last_cy
    dt=obs.get('dt',0.1) or 0.1
    mot=obs.get('motion',{}) or {}
    v=mot.get('v_mps',0.0) or 0.0
    st=obs.get('steer_deg',0.0) or 0.0
    phi=obs.get('hitch_deg',0.0) or 0.0
    rig=obs.get('rig',{}) or {}
    tr=rig.get('trailer_rear',[-1.6,0.0])
    th_t=rig.get('trailer_heading_deg',-phi)
    # odometry
    alley-=math.degrees(v*math.tan(math.radians(st))/L1*dt)
    # walls
    L=[];R=[]
    views=obs.get('views',{}) or {}
    for k,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0.1,0.0])
        for w in vw.get('walls',[]) or []:
            b,d=w[0],w[1]
            x=o[0]+d*math.cos(math.radians(b)); y=o[1]+d*math.sin(math.radians(b))
            if x>0.8 or x<-6.5: continue
            if abs(y)<0.7: continue
            (L if y>0 else R).append((x,y))
    fl=fit(L); fr=fit(R)
    slopes=[f[1] for f in (fl,fr) if f and f[1] is not None]
    if slopes:
        meas=math.degrees(math.atan(sum(slopes)/len(slopes)))
        if abs(meas-alley)<25:
            alley=0.7*alley+0.3*meas
    ta=math.tan(math.radians(alley))
    xr=tr[0]
    yl=yr=None
    if fl: yl=fl[0]+ta*(xr-fl[2])
    if fr: yr=fr[0]+ta*(xr-fr[2])
    cy=None
    if yl is not None and yr is not None:
        cy=(yl+yr)/2
        if 2.0<yl-yr<8: width=0.9*width+0.1*(yl-yr)
    elif yl is not None: cy=yl-width/2
    elif yr is not None: cy=yr+width/2
    tg=obs.get('target',{}) or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None and tg['dist_m']<9:
        tx=0.1+tg['dist_m']*math.cos(math.radians(tg['bearing_deg'])); ty=tg['dist_m']*math.sin(math.radians(tg['bearing_deg']))
        cyt=ty+ta*(xr-tx)
        cy=cyt if cy is None else 0.3*cy+0.7*cyt
    if cy is None: cy=last_cy if last_cy is not None else 0.0
    last_cy=cy
    e=(tr[1]-cy)*math.cos(math.radians(alley))
    a_d=clamp(17*e,-15,15)
    h=th_t-alley
    herr=h-a_d
    phi_d=clamp(0.6*herr,-25,25)
    look=170
    if phase=='rev':
        if abs(phi)>40:
            phase='fwd'
        else:
            ff=math.degrees(math.atan(1.47*math.sin(math.radians(phi))))
            steer=clamp(ff+2.5*(phi-phi_d),-45,45)
            sp=-0.7
            if abs(phi)>25: sp=-0.4
            return (steer,sp,look)
    if phase=='fwd':
        if abs(phi)<8:
            phase='rev'
            return (0.0,-0.5,look)
        steer=clamp(-0.3*h,-30,30)
        return (steer,0.8,look)
    return (0.0,0.0,look)

