import math
L=1.25
X=0.0;Y=0.0;PSI=0.0
pts={}
aim=[-3.0,3.2]
phase='fwd0'
fd=0.0

def ad(a):
    return (a+180.0)%360.0-180.0

def cl(x,a,b):
    return max(a,min(b,x))

def control(obs):
    global X,Y,PSI,phase,fd,aim
    dt=obs.get('dt') or 0.1
    mot=obs.get('motion') or {}
    v=mot.get('v_mps',0.0) or 0.0
    st=obs.get('steer_deg',0.0) or 0.0
    phi=obs.get('hitch_deg',0.0) or 0.0
    pr=math.radians(PSI)
    X+=v*math.cos(pr)*dt; Y+=v*math.sin(pr)*dt
    PSI+=math.degrees(v*math.tan(math.radians(st))/L*dt)
    c=math.cos(math.radians(PSI)); s=math.sin(math.radians(PSI))
    def w(x,y):
        return (X+x*c-y*s, Y+x*s+y*c)
    rig=obs.get('rig') or {}
    tr=rig.get('trailer_rear',[-1.6,0.0])
    tht=rig.get('trailer_heading_deg',-phi)
    R=w(tr[0],tr[1])
    corners=[]
    for k,vw in (obs.get('views') or {}).items():
        if not vw: continue
        o=vw.get('origin',[0.1,0.0])
        for p in vw.get('walls',[]) or []:
            b=math.radians(p[0]); x=o[0]+p[1]*math.cos(b); y=o[1]+p[1]*math.sin(b)
            wx,wy=w(x,y)
            pts[(round(wx*10),round(wy*10))]=(wx,wy)
        for p in vw.get('target_corners',[]) or []:
            try:
                b=math.radians(p[0]); x=o[0]+p[1]*math.cos(b); y=o[1]+p[1]*math.sin(b)
                corners.append(w(x,y))
            except Exception:
                pass
    if len(pts)>500:
        for kk in list(pts.keys()):
            q=pts[kk]
            if (q[0]-R[0])**2+(q[1]-R[1])**2>49: del pts[kk]
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None and tg['dist_m']<9:
        b=math.radians(tg['bearing_deg'])
        tw=w(0.1+tg['dist_m']*math.cos(b), tg['dist_m']*math.sin(b))
        aim=[0.7*aim[0]+0.3*tw[0],0.7*aim[1]+0.3*tw[1]]
    elif corners:
        mx=sum(q[0] for q in corners)/len(corners); my=sum(q[1] for q in corners)/len(corners)
        aim=[0.9*aim[0]+0.1*mx,0.9*aim[1]+0.1*my]
    look=170
    if phase=='fwd0':
        fd+=abs(v)*dt
        if fd<0.7:
            return (0.0,0.6,look)
        phase='rev'
    if phase=='fwd':
        if abs(phi)<12:
            phase='rev'
        else:
            return (0.0,0.7,look)
    if abs(phi)>45:
        phase='fwd'
        return (0.0,0.7,look)
    bt=PSI+180.0+tht
    dxa=aim[0]-R[0]; dya=aim[1]-R[1]
    da=math.hypot(dxa,dya)
    adir=math.degrees(math.atan2(dya,dxa))
    wa=1.0/40 if da>1.2 else 0.0
    P=list(pts.values())
    best=None; bs=-1e9
    for i in range(-20,21):
        a=bt+3*i
        ua=math.cos(math.radians(a)); va=math.sin(math.radians(a))
        f=3.5
        for q in P:
            dx=q[0]-R[0]; dy=q[1]-R[1]
            sa=dx*ua+dy*va
            if sa<0.2 or sa>=f: continue
            la=-dx*va+dy*ua
            if abs(la)<0.75: f=sa
        sc=f-abs(ad(a-adir))*wa-abs(3*i)/120.0
        if sc>bs: bs=sc; best=a
    bd=best
    ub=math.cos(math.radians(bt)); vb=math.sin(math.radians(bt))
    dr=9.0; dl=9.0
    for q in P:
        dx=q[0]-R[0]; dy=q[1]-R[1]
        sa=dx*ub+dy*vb
        if sa<-1.3 or sa>0.6: continue
        la=-dx*vb+dy*ub
        if la>0: dr=min(dr,la-0.475)
        else: dl=min(dl,-la-0.475)
    bd-=cl(30*(0.9-dr),0,20)
    bd+=cl(30*(0.9-dl),0,20)
    phi_d=cl(-1.2*ad(bd-bt),-30,30)
    ff=math.degrees(math.atan(1.47*math.sin(math.radians(phi))))
    steer=cl(ff+2.5*(phi-phi_d),-45,45)
    sp=-0.6 if da>1.5 else -0.35
    return (steer,sp,look)

