        if not S['woke']:
            S['woke']=True; wake('blocked: no free space behind')
    if S['n']%20==0:
        print('t',round(obs['t'],1),'h',round(h,1),'hd',round(hd,1),'st',round(st,1),'e',round(e,1),S.get('dbg'),'rem',rem)
    return (st,sp,-41.0)

